3: /**
4:  * Hooks the coordinator uses to integrate with reader-side state without
5:  * knowing how that state works. See ReaderScreen for the concrete wiring.
6:  */
7: export interface ReaderNavigationHooks {
8:   /** Called just before a user-initiated move (pace session break). */
9:   onBeforeMove: () => void;
10:   /**
11:    * Seek-gate mirror. While true, locator events are written through the
12:    * scrub path of the ProgressWriter instead of the continuous-reading path.
13:    */
14:   onSeekingChanged: (seeking: boolean) => void;
15: }
16: 
17: /**
18:  * Single coordination point for user-initiated navigation (04 ┬º5): page
19:  * clicks, keyboard, TOC, in-book search, scrubbing and Home/End all funnel
20:  * through here. The engine stays responsible for talking to Readium ΓÇö this
21:  * coordinator does not create or reconfigure the navigator.
22:  *
23:  * It owns exactly three things:
24:  * 1. the seek gate (with refcounting, so overlapping jumps cannot un-gate
25:  *    the writer while an earlier jump is still settling),
26:  * 2. outcome sequencing ΓÇö a request that resolves after a newer one has been
27:  *    issued is "superseded": its ok/failure no longer describes the reader's
28:  *    position and is not reported,
29:  * 3. a boolean contract at every call site, so failures can be surfaced.
30:  */
31: export class ReaderNavigationCoordinator {
32:   /** Id of the most recent request; completion results are compared to it. */
33:   private seq = 0;
34:   /** Number of navigation requests currently resolving. */
35:   private inflight = 0;
36:   /** In-flight requests that gate the seek state. */
37:   private seekGated = 0;
38: 
39:   constructor(
40:     private readonly engine: ReaderEngine,
41:     private readonly hooks: ReaderNavigationHooks
42:   ) {}
43: 
44:   /**
45:    * Was a navigation issued through this coordinator and is it still
46:    * resolving? ReaderScreen can use this to avoid double-handling.
47:    */
48:   get busy(): boolean {
49:     return this.inflight > 0;
50:   }
51: 
52:   /** Next page (right zone, ArrowRight/PageDown/Space). Not seek-gated:
53:    * continuous reading ΓÇö locator events flow through the normal writer path. */
54:   async next(): Promise<boolean> {
55:     this.assertEngine();
56:     this.hooks.onBeforeMove();
57:     return this.run(false, () => this.engine.goForward());
58:   }
59: 
60:   /** Previous page (left zone, ArrowLeft/PageUp/Shift+Space). */
61:   async previous(): Promise<boolean> {
62:     this.assertEngine();
63:     this.hooks.onBeforeMove();
64:     return this.run(false, () => this.engine.goBackward());
65:   }
66: 
67:   /** Chapter navigation: TOC picks and in-book search hits. */
68:   async goToHref(href: string): Promise<boolean> {
69:     if (!href) return false;
70:     this.assertEngine();
71:     this.hooks.onBeforeMove();
72:     return this.run(true, () => this.engine.go(href));
73:   }
74: 
75:   /** Progress jump: scrub release, Home/End. Clamped to 0..100. */
76:   async goToPercent(percent: number): Promise<boolean> {
77:     if (!Number.isFinite(percent)) return false;
78:     const clamped = Math.min(100, Math.max(0, percent));
79:     this.assertEngine();
80:     this.hooks.onBeforeMove();
81:     return this.run(true, () => this.engine.go({ percent: clamped }));
82:   }
83: 
84:   private async run(seek: boolean, nav: () => Promise<boolean>): Promise<boolean> {
85:     const id = ++this.seq;
86:     this.inflight++;
87:     if (seek) {
88:       this.seekGated++;
89:       this.hooks.onSeekingChanged(true);
90:     }
91:     try {
92:       const ok = await nav();
93:       // A newer request has been issued since; it owns the position, so the
94:       // stale outcome is not allowed to look like a failure.
95:       return id === this.seq ? ok : true;
96:     } finally {
97:       this.inflight--;
98:       if (seek) {
99:         this.seekGated--;
100:         if (this.seekGated === 0) this.hooks.onSeekingChanged(false);
101:       }
102:     }
103:   }
