1: // Reading pace (04 ┬º9, 1:1 port of ReadingPaceStats.kt math):
2: // accumulate wall-clock ONLY between two *forward* continuous moves
3: // (delta < 5 percentage points). Jumps/scrubs/suspension break the session;
4: // backward moves never credit. Time-to-finish formula guarded on percentRead.
5: 
6: export interface PaceState {
7:   sessionsMs: number;
8:   percentRead: number;
9: }
10: 
11: const CONTINUOUS_DELTA_PP = 5;
12: 
13: export class ReadingPaceStats {
14:   private sessionsMs: number;
15:   private percentRead: number;
16:   private anchorTs: number | null = null;
17:   private anchorPercent: number | null = null;
18: 
19:   constructor(state?: PaceState | null) {
20:     this.sessionsMs = Math.max(0, state?.sessionsMs ?? 0);
21:     this.percentRead = Math.max(0, state?.percentRead ?? 0);
22:   }
23: 
24:   /** A continuous forward move (page turn forward). `percent` 0..100. */
25:   onForwardMove(percent: number, nowMs: number): void {
26:     const clamped = Math.min(100, Math.max(0, percent));
27:     if (this.anchorTs === null || this.anchorPercent === null) {
28:       // first move of the session: anchor only, no credit yet
29:       this.anchorTs = nowMs;
30:       this.anchorPercent = clamped;
31:     } else {
32:       const delta = clamped - this.anchorPercent;
33:       if (delta > 0 && delta < CONTINUOUS_DELTA_PP) {
34:         this.sessionsMs += nowMs - this.anchorTs;
35:         this.anchorTs = nowMs;
36:         this.anchorPercent = clamped;
37:       } else if (delta >= CONTINUOUS_DELTA_PP) {
38:         // jump ΓÇö do not credit the gap; re-anchor
39:         this.anchorTs = nowMs;
40:         this.anchorPercent = clamped;
41:       } else {
42:         // backward or same position ΓÇö no credit; re-anchor so the gap before
43:         // the back-move isn't credited later
44:         this.anchorTs = nowMs;
45:         this.anchorPercent = clamped;
46:       }
47:     }
48:     if (clamped > this.percentRead) this.percentRead = clamped;
49:   }
50: 
51:   /** Jump / scrub / sheet open / suspension: break the session without credit. */
52:   breakSession(nowMs: number): void {
53:     this.anchorTs = nowMs;
54:     this.anchorPercent = null;
55:   }
56: 
57:   /** Current persisted state. */
58:   state(): PaceState {
59:     return { sessionsMs: Math.round(this.sessionsMs), percentRead: Math.round(this.percentRead * 10) / 10 };
60:   }
61: 
62:   /** Time-to-finish minutes (04 ┬º9): sessionsMs/1000/60 ├ù ((100ΓêÆp)/percentRead). */
63:   timeLeftMinutes(percent: number): number | null {
64:     const p = Math.min(100, Math.max(0, percent));
65:     if (this.percentRead <= 0 || p >= 100) return null;
66:     const readFraction = this.percentRead / 100;
67:     if (readFraction <= 0) return null;
68:     const remainingFraction = (100 - p) / 100;
69:     const minutes = (this.sessionsMs / 1000 / 60) * (remainingFraction / readFraction);
70:     if (!Number.isFinite(minutes) || minutes < 0) return null;
71:     return minutes;
