41:     let cur = i;
42:     for (let j = 1; j <= b.length; j++) {
43:       const cost = a[i - 1] === b[j - 1] ? 0 : 1;
44:       const v = Math.min(prev[j] + 1, cur + 1, prev[j - 1] + cost);
45:       prev[j - 1] = cur;
46:       cur = v;
47:     }
48:     prev[b.length] = cur;
49:   }
50:   return prev[b.length];
