export const EDGE_ZONE_RATIO = 0.08;
export const EDGE_ZONE_MIN_PX = 48;
export const EDGE_ZONE_MAX_PX = 96;

export function edgeZoneWidth(width: number): number {
  if (!(width > 0)) return 0;
  return Math.min(EDGE_ZONE_MAX_PX, Math.max(EDGE_ZONE_MIN_PX, width * EDGE_ZONE_RATIO));
}

export function intentForReaderClick(info: ReaderClickInput): ReaderClickIntent {
  if (info.interactive || info.defaultPrevented) return "passthrough";
  const edge = edgeZoneWidth(info.width);
  if (info.x < edge) return "previous";
  if (info.x > info.width - edge) return "next";
  if (info.column) {
    // Blank margins outside the reading column reveal the chrome.
    if (info.x < info.column.left || info.x > info.column.right) return "reveal";
    return "passthrough";
  }
  return "passthrough";
}
```

