  private scrubGraceUntil: number | null = null;

  constructor(private now = () => Date.now()) { this.lastActivityTs = this.now(); }

  get visible() { return this.visibility === "visible"; }
  get held(): boolean { return this.holds.size > 0; }

  onActivity() { this.lastActivityTs = this.now(); this.pillarHoverUntil = 0; this.visibility = "visible"; }

  onPillarHover() { this.pillarHoverUntil = this.now() + PILLAR_HOVER_MS; this.visibility = "visible"; }

  hold(reason) { const first = !this.holds.has(reason); this.holds.add(reason); if (first) { this.visibility = "visible"; this.lastActivityTs = this.now(); } }

  release(reason) { if (this.holds.delete(reason)) this.lastActivityTs = this.now(); }

  toggle(): ChromeVisibility {
    // Never hide under an open menu/panel/dialog or while the user is
    // interacting with the controls.
    if (this.held) { this.visibility = "visible"; return this.visibility; }
    this.visibility = this.visible ? "hidden" : "visible";
    this.pillarHoverUntil = 0;
    if (this.visible) this.lastActivityTs = this.now();
    return this.visibility;
  }

  onScrubStart() { this.scrubGraceUntil = null; this.hold("scrub"); }
  onScrubEnd() { this.release("scrub"); this.scrubGraceUntil = this.now() + SCRUB_GRACE_MS; }

  tick(): ChromeVisibility {
    const now = this.now();
    if (this.holds.size > 0) { this.visibility = "visible"; return this.visibility; }
    if (this.scrubGraceUntil !== null) {
      if (now < this.scrubGraceUntil) { this.visibility = "visible"; return this.visibility; }
