Current block starts:
```ts
    const onKey = (event: KeyboardEvent) => {
      if (event.defaultPrevented || event.repeat || isTypingTarget(event.target)) return;
      const engine = engineRef.current;
      if (!engine) return;

      const turn = (direction: "next" | "previous") => {
