input.newString:
/* ---- Chrome (03 ┬º5.3) ΓÇö surface per resolved reading theme ----------------
   The chrome is one overlay (top bar + bottom dock) over the canvas. The
   container itself is click-through so the publication keeps every pixel
   between the controls; only the bars accept pointer events. */
.folio-reader-chrome {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
  transition: opacity var(--folio-motion-panel) var(--folio-motion-panel-ease);
  opacity: 1;
}

.folio-reader-chrome.is-visible {
  opacity: 1;
}

.folio-reader-chrome:not(.is-visible) {
  opacity: 0;
}

.folio-reader-chrome:not(.is-visible) .folio-reader-top,
.folio-reader-chrome:not(.is-visible) .folio-reader-dock {
  visibility: hidden;
}

/* Top bar (04 ┬º5.3 / 03 ┬º5.3): back ┬╖ title ┬╖ reading tools. */
.folio-reader-top {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: var(--folio-space-2);
  height: 56px;
  padding: 0 var(--folio-space-3);
  pointer-events: auto;
  background: color-mix(in srgb, var(--reader-chrome-surface, rgba(255, 254, 251, 0.92)) 92%, transparent);
  color: var(--reader-chrome-text, #1C1B19);
  border-bottom: var(--folio-divider) solid color-mix(in srgb, currentColor 10%, transparent);
  backdrop-filter: blur(14px);
}

.folio-reader-top__group {
  display: flex;
  align-items: center;
  gap: 2px;
}

