/* Bottom dock (04 ┬º5): Previous ┬╖ position ┬╖ Next, then the progress slider.
   Rounded card rather than a full-width bar, so the page keeps its edges. */
.folio-reader-dock {
  width: min(720px, calc(100% - var(--folio-space-5)));
  margin: 0 auto var(--folio-space-4);
  padding: 8px var(--folio-space-3) 6px;
  display: flex;
  flex-direction: column;
  gap: 2px;
  pointer-events: auto;
  border-radius: var(--folio-radius-panel);
  border: var(--folio-divider) solid color-mix(in srgb, currentColor 10%, transparent);
  background: color-mix(in srgb, var(--reader-chrome-surface, rgba(255, 254, 251, 0.92)) 94%, transparent);
  color: var(--reader-chrome-text, #1C1B19);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.14);
  backdrop-filter: blur(14px);
