   container itself is click-through so the publication keeps every pixel
   between the controls; only the bars accept pointer events. */
.folio-reader-chrome {
  position: absolute;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  pointer-events: none;
  transition: opacity var(--folio-motion-panel) var(--folio-motion-panel-ease);
  opacity: 1;
}

.folio-reader-chrome.is-visible {
  opacity: 1;
}

.folio-reader-chrome:not(.is-visible) {
  opacity: 0;
}

.folio-reader-chrome:not(.is-visible) .folio-reader-top,
.folio-reader-chrome:not(.is-visible) .folio-reader-dock {
  visibility: hidden;
}

